func withFile(path string, fn func(*os.File) error) (err error) {
    f, err := os.Open(path)
    if err != nil {
        return err
    }
    defer func() { err = errors.Join(err, f.Close()) }()   // teardown merges into the named result
    return fn(f)                                           // body as an argument
}
